/// Builds `endpoint` without and with a token and checks the request.
fn check<E: Endpoint>(endpoint: &E, path: &str, query: &[&str]) {
    let anonymous = Session::new(ServerUrl::official(), None).request(endpoint);
    if E::AUTH == Auth::Required {
        assert!(
            matches!(anonymous, Err(RequestError::MissingToken)),
            "{path}"
        );
    } else {
        assert!(anonymous.is_ok(), "{path}");
    }
    let session = Session::new(ServerUrl::official(), Some(Token::new("test-token")));
    let request = session.request(endpoint).unwrap();
    assert_eq!(request.method(), E::METHOD);
    assert_eq!(request.uri().path(), path);
    let sent: Vec<&str> = request
        .uri()
        .query()
        .map_or_else(Vec::new, |query| query.split('&').collect());
    assert_eq!(sent, query, "{path}");
    assert_eq!(request.headers()["x-token"], "test-token");
    if request.body().is_empty() {
        assert!(request.headers().get(CONTENT_TYPE).is_none(), "{path}");
    } else {
        assert_eq!(
            request.headers()[CONTENT_TYPE],
            "application/json",
            "{path}"
        );
        serde_json::from_slice::<serde_json::Value>(request.body()).unwrap();
    }
}

